commits.content:
.loader-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-color: #000000;
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 9999;
}

.loader-logo {
    width: 100px;
    height: 100px;
    border: 2px solid #4a4a4a;
    border-radius: 50%;
    position: relative;
    animation: scale-in-out 1s cubic-bezier(0.4, 0, 0.2, 1) infinite alternate;
}

.loader-logo::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 50px;
    height: 50px;
    background-color: #4a4a4a;
    border-radius: 50%;
    transform: translate(-50%, -50%);
}
